-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.admin_decline_application(target uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text; v_email text;
begin
  if not public.is_admin() then raise exception 'Not allowed'; end if;
  select name into v_name from public.profiles where id = target;
  if v_name is null then raise exception 'Creator not found'; end if;
  select email into v_email from auth.users where id = target;
  insert into public.application_decisions (creator_id, creator_name, email, decision, decided_by)
  values (target, v_name, v_email, 'declined', auth.uid());
  perform public.admin_delete_creator(target);
end $function$;
